import{_ as a,o as n,a as p,b as c}from"./app.DKoEZOcr.js";const t="/ascendc.github.io/pr/5487/assets/no_l2_cache_split.BY-VBjIk.png",l="/ascendc.github.io/pr/5487/assets/l2_cache_split.DyyvDkUS.png",e="/ascendc.github.io/pr/5487/assets/l2cache_to_UB.DdrohiKT.png",o="/ascendc.github.io/pr/5487/assets/l2cache_fill_process.DwbCL23u.png",d="/ascendc.github.io/pr/5487/assets/l2cache_no_split_example.D3_iZA1S.png",h="/ascendc.github.io/pr/5487/assets/l2cache_split_example.5cq8eVtp.png",L=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子性能优化","link":"/guide/operator_practice/simd_operator_optimization/simd_operator_optimization"},{"text":"内存访问","link":"/guide/operator_practice/simd_operator_optimization/memory_access/memory_access"},{"text":"L2 Cache切分","link":"/guide/operator_practice/simd_operator_optimization/memory_access/l2_cache_split"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_optimization/memory_access/l2_cache_split.md","filePath":"guide/operator_practice/simd_operator_optimization/memory_access/l2_cache_split.md","outlineHeaders":[{"level":2,"title":"场景设定","slug":"场景设定","link":"#场景设定"},{"level":2,"title":"反例：不做L2 Cache切分","slug":"反例：不做L2-Cache切分","link":"#反例：不做L2-Cache切分"},{"level":2,"title":"正例：按L2 Cache切分","slug":"正例：按L2-Cache切分","link":"#正例：按L2-Cache切分"},{"level":2,"title":"为什么不切分会降低复用概率","slug":"为什么不切分会降低复用概率","link":"#为什么不切分会降低复用概率"},{"level":2,"title":"公共处理逻辑","slug":"公共处理逻辑","link":"#公共处理逻辑"},{"level":2,"title":"正反例对比总结","slug":"正反例对比总结","link":"#正反例对比总结"},{"level":2,"title":"适用场景","slug":"适用场景","link":"#适用场景"},{"level":2,"title":"测试用例设计","slug":"测试用例设计","link":"#测试用例设计"},{"level":3,"title":"正反例用例","slug":"正反例用例","link":"#正反例用例"},{"level":3,"title":"验证检查点","slug":"验证检查点","link":"#验证检查点"}],"lastUpdated":1788782397000}'),r={name:"guide/operator_practice/simd_operator_optimization/memory_access/l2_cache_split.md"};function i(_,s,g,B,w,C){return n(),p("div",null,[...s[0]||(s[0]=[c('<div><article class="markdown-body"><h1>L2 Cache切分<span id="ZH-CN_TOPIC_0000001893038949"></span></h1><p>【优先级】：高</p><p>【描述】假设，AI处理器的L2 Cache大小为192MB，L2 Cache读写混合带宽约为7TB/s，而GM的带宽约为1.6TB/s，两者之间存在较大差距。搬入或搬出相同数据量的情况下，访问L2 Cache读写数据比GM更快。若数据无法命中L2 Cache，即需要访问的数据不在L2 Cache内，导致需要去GM上读写，带宽利用效率较低，最终算子搬入或搬出数据变为算子整个运行过程的性能瓶颈。切分策略建议：当输入和输出数据的数据量超过L2 Cache大小时，Tiling中开启L2 Cache切分策略。</p><p>优化的核心思路是：<strong>通过开启L2 Cache切分策略，将单轮处理的数据规模控制在L2 Cache范围内，提升数据在L2 Cache中的复用率，从而减少重复的数据搬入或搬出</strong>。本文及配套样例将L2 Cache可容纳的有效数据量阈值设为100MB，该取值仅用于样例展示。</p><h2 id="场景设定">场景设定<a class="header-anchor" href="#场景设定">​</a></h2><ul><li>使用20个Vector Core并行计算，每个元素执行两轮“加1”运算，最终结果为<code>data + 2</code>。</li><li>反例不做L2 Cache切分，每轮把384MB数据作为一个整体进行搬入、计算、搬出。</li><li>正例将384MB数据切分成B0至B3四个L2 Batch，每批包含96MB的数据量，每一批进行两轮加1计算。</li><li>完整实现方法请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/10_cache_control/add_l2_cache_split">add_l2_cache_split样例</a>。</li></ul><p>两个场景的数据处理方式如下图所示。</p><p><strong>图 1</strong> 未开启L2 Cache切分<span id="fig_l2_cache_no_split"></span></p><p><img src="'+t+'" alt title="未开启L2-Cache切分"></p><p><strong>图 2</strong> 开启L2 Cache切分<span id="fig_l2_cache_split"></span></p><p><img src="'+l+'" alt title="开启L2-Cache切分"></p><h2 id="反例：不做L2-Cache切分">反例：不做L2 Cache切分<a class="header-anchor" href="#反例：不做L2-Cache切分">​</a></h2><p>反例中不做数据切分，直接处理384MB数据整体。L2 Cache对用户不可见，用户可感知数据从GM搬运到UB的过程为：384MB总数据由20个核均分，平均每个核搬运约19.2MB。</p><p><strong>【用户视角】</strong></p><p>只感知GM到UB搬运过程，384MB总数据由20个核均分搬运，每个核搬运19.2MB。</p><p><strong>【实际数据路径】</strong></p><p>输入数据会先从GM填充到L2 Cache，再到UB。</p><p><strong>图 3</strong> GM搬运到UB路径<span id="fig_l2_cache_gm_to_ub"></span></p><p><img src="'+e+'" alt title="GM搬运到UB路径"></p><p><strong>【搬运填充过程】</strong></p><p>假设20个核处理的数据按核序逐段搬入L2 Cache，L2 Cache有效数据阈值为100MB，则L2 Cache内约可容纳5个核的数据量。</p><p><strong>图 4</strong> 数据搬运填充L2 Cache过程<span id="fig_l2_cache_fill_process"></span></p><p><img src="'+o+'" alt title="数据搬运填充L2 Cache过程"></p><p>后续新数据填充L2 Cache时，可能替换核0~核4早期Cache Line。</p><p><strong>【不切分反例的执行时序】</strong></p><p><strong>图 5</strong> 未开启L2 Cache切分反例<span id="fig_l2_cache_no_split_example"></span></p><p><img src="'+d+`" alt title="未开启L2 Cache切分反例"></p><p>在第1轮（R0）处理384MB后半段数据时，后续搬入的新数据可能会替换先前搬入的数据。由于R0是首轮访问，仅比较一轮搬运计算不能稳定体现L2 Cache命中收益；第2轮（R1）再次访问384MB数据时，先前的数据可能已经不在L2 Cache中，因此更可能从GM重新搬运。</p><h2 id="正例：按L2-Cache切分">正例：按L2 Cache切分<a class="header-anchor" href="#正例：按L2-Cache切分">​</a></h2><p>在正例中，根据阈值100MB， 对384MB数据进行切分，分成4个Batch，每份96MB。每轮20核共处理96MB数据，每轮数据复用，这样每次计算前读取的数据能够命中L2 Cache，提升算子性能。 正例的循环层级为<code>L2 Batch -&gt; Round</code>。同一批连续完成全部轮次后，再切换到下一批：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>L2 Batch数      = ceil(总数据量 / L2 Cache有效数据阈值)
                = ceil(384MB / 100MB)
                = 4
单个L2 Batch大小 = 384MB / 4 = 96MB
</code></pre></div><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">l2BatchIdx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">l2BatchIdx</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">L2_BATCH_NUM</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">l2BatchIdx</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">roundIdx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">roundIdx</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">COMPUTE_ROUND_NUM</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">roundIdx</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">ProcessL2Batch</span><span class="p">(</span><span class="n">l2BatchIdx</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">SyncAll</span><span class="p">();</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p><strong>【L2 Cache切分正例的执行时序】</strong></p><p><strong>图 6</strong> 开启切分正例<span id="fig_l2_cache_split_example"></span></p><p><img src="`+h+`" alt title="开启切分正例"></p><p>同一Batch的两轮访问之间，没有插入其他超过100MB有效阈值的大数据，因此第2轮更有机会命中第1轮留在L2 Cache中的数据。<br> B0的数据量为96MB，不超过100MB阈值；B0在两次访问之间也没有其他大数据插入更新L2 Cache，因此R1更有机会从L2 Cache读取R0的结果。B0处理完毕后再依次处理B1至B3，原理相同。</p><p><strong>【性能观察重点】</strong></p><p>只执行一轮计算：R0是首轮访问，反例和正例都需要从GM首次搬入数据，Cache Miss差异通常不明显。<br> 正反例通过对L2 Cache中数据复用程度体现性能优化：R1再次访问同一批地址时，目标数据是否仍在L2 Cache中，才是减少Cache Miss的关键。<br></p><p>反例的循环层级为<code>Round -&gt; Whole Data</code>。外层每轮都处理完整384MB范围：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">roundIdx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">roundIdx</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">COMPUTE_ROUND_NUM</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">roundIdx</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">ProcessWholeData</span><span class="p">();</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">SyncAll</span><span class="p">();</span>
<span class="p">}</span>
</code></pre></div><p><strong>表 1</strong> 样例数据量</p><table><thead><tr><th>数据量</th><th>计算方法</th><th align="right">结果</th></tr></thead><tbody><tr><td>总数据量</td><td>样例固定值</td><td align="right">384MB</td></tr><tr><td>总元素数</td><td><code>384MB / sizeof(half)</code></td><td align="right">201326592</td></tr><tr><td>L2 Cache有效数据阈值</td><td>样例固定值</td><td align="right">100MB</td></tr><tr><td>反例单阶段全核数据</td><td>不做L2 Cache切分</td><td align="right">384MB</td></tr><tr><td>正例L2 Batch数</td><td><code>ceil(384MB / 100MB)</code></td><td align="right">4</td></tr><tr><td>正例单个L2 Batch数据量</td><td><code>384MB / 4</code></td><td align="right">96MB</td></tr><tr><td>正例单个L2 Batch元素数</td><td><code>96MB / sizeof(half)</code></td><td align="right">50331648</td></tr></tbody></table><h2 id="为什么不切分会降低复用概率">为什么不切分会降低复用概率<a class="header-anchor" href="#为什么不切分会降低复用概率">​</a></h2><p>以本文100MB阈值为例，核0至核4合计处理约96MB，已经接近L2 Cache有效容量；当核5及后续核继续搬入新数据时，总数据量超过100MB阈值，核0等较早进入L2 Cache的数据就可能被替换。也就是说，替换风险在第1轮处理过程中已经产生，不是等到第2轮才产生。如果算子在同一轮后续步骤就复用早期地址，这种替换会在单轮内直接表现为Cache Miss。<br> 文档中设计两轮计算，是为了显式体现数据复用：第2轮再次访问第1轮刚处理过的同一批地址。不切分时，第2轮重新访问<code>data[0]</code>所在地址范围，先前数据可能已经在第1轮后续扫描中被替换，因此更可能发生Cache Miss并从GM重新取数。<br> L2 Cache切分正例将单个循环需要处理的数据量限制在96MB。单个Batch内，20个核合计覆盖的数据量不超过100MB阈值，每个核只处理约4.8MB。先在<code>data[B0]</code>上完成第1轮和第2轮计算，再依次处理B1至B3。同一批两轮访问之间没有插入其他大数据更新L2 Cache，因此第2轮更有机会直接命中第1轮刚写回的L2 Cache数据。<br></p><h2 id="公共处理逻辑">公共处理逻辑<a class="header-anchor" href="#公共处理逻辑">​</a></h2><p>两种实现都使用同一份<code>data</code> Buffer，并将结果写回搬入时的同一GM地址。差异在于传给公共处理函数的连续数据范围不同：反例传入完整384MB范围，正例传入单个96MB L2 Batch范围。以下代码仅展示实际样例采用的32字节DataBlock分核公式和正反例传入范围差异，不展开单核内部搬运和计算细节。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">ProcessWholeData</span><span class="p">()</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">ProcessDataRange</span><span class="p">(</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">TOTAL_DATA_ELEMENTS</span><span class="p">);</span>
<span class="p">}</span>

<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">ProcessL2Batch</span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">l2BatchIdx</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">ProcessDataRange</span><span class="p">(</span><span class="n">l2BatchIdx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">L2_BATCH_ELEMENTS</span><span class="p">,</span><span class="w"> </span><span class="n">L2_BATCH_ELEMENTS</span><span class="p">);</span>
<span class="p">}</span>

<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">ProcessDataRange</span><span class="p">(</span><span class="kt">int64_t</span><span class="w"> </span><span class="n">rangeOffsetInData</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">rangeElementNum</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">coreIdx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetBlockIdx</span><span class="p">();</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">rangeDataBlockNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">rangeElementNum</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">ELEMENTS_PER_DATA_BLOCK</span><span class="p">;</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">baseDataBlocksPerCore</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">rangeDataBlockNum</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">VECTOR_CORE_NUM</span><span class="p">;</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">coresWithExtraDataBlock</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">rangeDataBlockNum</span><span class="w"> </span><span class="o">%</span><span class="w"> </span><span class="n">VECTOR_CORE_NUM</span><span class="p">;</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">extraDataBlockNumBeforeCore</span><span class="w"> </span><span class="o">=</span>
<span class="w">        </span><span class="n">coreIdx</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">coresWithExtraDataBlock</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="n">coreIdx</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="n">coresWithExtraDataBlock</span><span class="p">;</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">coreDataBlockNum</span><span class="w"> </span><span class="o">=</span>
<span class="w">        </span><span class="n">baseDataBlocksPerCore</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="p">(</span><span class="n">coreIdx</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">coresWithExtraDataBlock</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="mi">1U</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="mi">0U</span><span class="p">);</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">coreDataBlockOffset</span><span class="w"> </span><span class="o">=</span>
<span class="w">        </span><span class="n">coreIdx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">baseDataBlocksPerCore</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">extraDataBlockNumBeforeCore</span><span class="p">;</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">coreElementNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">coreDataBlockNum</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">ELEMENTS_PER_DATA_BLOCK</span><span class="p">;</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">int64_t</span><span class="w"> </span><span class="n">coreOffsetInData</span><span class="w"> </span><span class="o">=</span>
<span class="w">        </span><span class="n">rangeOffsetInData</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">int64_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">coreDataBlockOffset</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">ELEMENTS_PER_DATA_BLOCK</span><span class="p">;</span>
<span class="w">    </span><span class="n">ProcessCoreRange</span><span class="p">(</span><span class="n">coreOffsetInData</span><span class="p">,</span><span class="w"> </span><span class="n">coreElementNum</span><span class="p">);</span>
<span class="p">}</span>

<span class="c1">// 单核内部搬运和计算流程以配套样例完整实现为准。</span>
</code></pre></div><p>对于不切分反例的384MB整体范围，前12个核各处理629146个DataBlock，其余8个核各处理629145个DataBlock，单核数据量约19.2MB，20个核合计覆盖完整<code>data[0, 384MB)</code>范围且互不重叠。对于正例的单个96MB L2 Batch，前8个核各处理157287个DataBlock，其余12个核各处理157286个DataBlock，单核数据量约4.8MB，20个核合计覆盖完整L2 Batch且互不重叠。每个DataBlock包含16个<code>half</code>元素，因此所有<code>DataCopy</code>搬运的数据长度均满足32字节对齐要求。完整核内流水同步实现以配套样例为准；阶段之间的核间同步由配套样例的<code>KernelAdd::SyncAllCores</code>函数直接调用API<code>AscendC::SyncAll()</code>接口完成，不是额外封装的自定义同步函数。</p><h2 id="正反例对比总结">正反例对比总结<a class="header-anchor" href="#正反例对比总结">​</a></h2><p><strong>表 2</strong> 正反例对比</p><table><thead><tr><th>维度</th><th>反例</th><th>正例</th></tr></thead><tbody><tr><td>L2 Cache切分</td><td>不切分</td><td>切分为4个96MB L2 Batch</td></tr><tr><td>循环层级</td><td><code>Round -&gt; Whole Data</code></td><td><code>L2 Batch -&gt; Round</code></td></tr><tr><td>单阶段全核数据量</td><td>384MB</td><td>96MB</td></tr><tr><td>单核平均处理量</td><td>约19.2MB</td><td>约4.8MB</td></tr><tr><td>执行时间线</td><td><code>R0/data[0,384MB) -&gt; R1/data[0,384MB)</code></td><td><code>B0/R0 -&gt; B0/R1 -&gt; ... -&gt; B3/R0 -&gt; B3/R1</code></td></tr><tr><td>同一批两次访问之间</td><td>一轮内20核已合计扫描完整384MB范围</td><td>不插入其他超过阈值的大数据范围</td></tr><tr><td>L2 Cache数据替换风险</td><td>较高</td><td>较低</td></tr><tr><td>第2轮L2 Cache命中率</td><td>预期较低，以实测为准</td><td>预期较高，以实测为准</td></tr></tbody></table><h2 id="适用场景">适用场景<a class="header-anchor" href="#适用场景">​</a></h2><ul><li>算子总数据量超过可用的L2 Cache有效阈值，且同一批数据需要被多次读取。</li><li>只读取一次的数据不存在跨Round复用，调整L2 Cache切分顺序通常收益有限。</li></ul><h2 id="测试用例设计">测试用例设计<a class="header-anchor" href="#测试用例设计">​</a></h2><p>测试正反例使用相同的384MB的GM数据Buffer、核数、Round数和计算逻辑。唯一核心差异是反例不做L2 Cache切分，正例中输入数据按100MB有效数据阈值切分为4个96MB L2 Batch。</p><h3 id="正反例用例">正反例用例<a class="header-anchor" href="#正反例用例">​</a></h3><p><strong>表 3</strong> 正反例用例</p><table><thead><tr><th>用例</th><th>循环层级</th><th>数据元素数</th><th align="right">核数</th><th>Round数</th><th align="right">验证目的</th></tr></thead><tbody><tr><td>反例no-split</td><td><code>Round -&gt; Whole Data</code></td><td>201326592</td><td align="right">20</td><td>2</td><td align="right">验证20核合计384MB数据量超过L2 Cache有效阈值时的替换风险</td></tr><tr><td>正例L2-split</td><td><code>L2 Batch -&gt; Round</code></td><td>201326592</td><td align="right">20</td><td>2</td><td align="right">验证单个96MB Batch连续复用带来的L2 Cache局部性改善</td></tr></tbody></table><p>正例每个L2 Batch包含50331648个<code>half</code>元素，占96MB。以32字节DataBlock为最小单位分配给20个Vector Core，前8个核各处理2516592个元素，其余12个核各处理2516576个元素。反例每轮直接处理完整384MB范围，20个核共同覆盖<code>data[0,384MB)</code>。所有<code>DataCopy</code>长度均保持32字节对齐。</p><h3 id="验证检查点">验证检查点<a class="header-anchor" href="#验证检查点">​</a></h3><p><strong>表 4</strong> 验证检查点</p><table><thead><tr><th>检查项</th><th>验证方法</th><th>预期结果</th></tr></thead><tbody><tr><td>L2 Cache命中率</td><td>独立进程采集L2 Cache读命中指标</td><td>正例中位数通常高于反例，具体字段按架构和工具版本解释</td></tr><tr><td>搬运效率</td><td>对比MTE2耗时和有效带宽</td><td>正例MTE2耗时中位数通常降低，有效带宽通常提升</td></tr><tr><td>端到端耗时</td><td>正反例各采集多组独立Profile并比较<code>Task Duration(us)</code>中位数</td><td>搬运受限场景下，正例耗时通常低于反例</td></tr></tbody></table><blockquote><p><strong>说明</strong>：<code>aiv_gm_to_ub_bw(GB/s)</code>表示有效带宽，不表示GM读取量。优化后有效带宽可能升高，不能以“带宽更低”作为预期。性能采集应交替安排正反例的先后顺序，并使用多组结果的中位数降低系统波动影响。</p></blockquote></article></div>`,1)])])}const u=a(r,[["render",i]]);export{L as __pageData,u as default};
